import csv
import io
import re
import typing

def _is_blank(row: typing.List[str]) -> bool:
    return not row or all(str(value).strip() == "" for value in row)

def _looks_like_date(value: str) -> bool:
    value = value.strip()
    return bool(re.fullmatch(r"\d{1,4}[./-]\d{1,2}[./-]\d{1,4}", value))

def _looks_like_time(value: str) -> bool:
    return bool(re.fullmatch(r"\d{1,2}:\d{2}(?::\d{2})?", value.strip()))

def _looks_numeric(value: str) -> bool:
    return bool(re.fullmatch(r"[-+]?(?:\d+(?:\.\d*)?|\.\d+)", value.strip()))

def _looks_like_url(value: str) -> bool:
    return bool(re.match(r"^[a-z][a-z0-9+.-]*://", value.strip(), re.I))

def _header_score(row: typing.List[str], following: typing.Optional[typing.List[str]]) -> int:
    if not row:
        return -100
    score = 0
    for value in row:
        text = value.strip()
        if text and re.search(r"[A-Za-z]", text):
            score += 1
        if _looks_like_date(text) or _looks_like_time(text):
            score -= 3
        elif _looks_numeric(text) or _looks_like_url(text):
            score -= 2
    if following and not _is_blank(following):
        data_score = 0
        if following and _looks_like_date(following[0]):
            data_score += 2
        if len(following) > 1 and _looks_like_time(following[1]):
            data_score += 1
        if any(_looks_numeric(x) for x in following[2:]):
            data_score += 1
        score += data_score
    return score

def _field_kind(name: str) -> str:
    text = name.strip().lower()
    if re.search(r"\b(date|day|month|year)\b", text):
        return "date"
    if re.search(r"\b(time|hour|minute)\b", text):
        return "time"
    if re.search(r"\b(qty|quantity|count|number|num|amount)\b", text):
        return "number"
    if re.search(r"\b(price|cost|amount|value|total)\b", text):
        return "money"
    if re.search(r"\b(url|uri|link|website|web)\b", text):
        return "url"
    return ""

def _matches_kind(value: str, kind: str) -> bool:
    if kind == "date":
        return _looks_like_date(value)
    if kind == "time":
        return _looks_like_time(value)
    if kind in ("number", "money"):
        cleaned = value.strip().replace("$", "").replace(",", "")
        return _looks_numeric(cleaned)
    if kind == "url":
        return _looks_like_url(value)
    return True

def _normalize_row(
    row: typing.List[str],
    width: int,
    headers: typing.Optional[typing.List[str]] = None
) -> typing.List[str]:
    row = ["" if value is None else str(value) for value in row]
    if len(row) == width:
        return row
    if len(row) < width:
        return row + [""] * (width - len(row))
    if width <= 0:
        return []

    kinds = [_field_kind(headers[i]) if headers and i < len(headers) else ""
             for i in range(width)]
    extra = len(row) - width
    best_position = width - 1
    best_score = None

    for position in range(0, len(row) - extra):
        candidate = row[:position] + [",".join(row[position:position + extra + 1])] + row[position + extra + 1:]
        score = 0
        constrained = 0
        for index, kind in enumerate(kinds):
            if kind:
                constrained += 1
                if _matches_kind(candidate[index], kind):
                    score += 4
                else:
                    score -= 5
        merged = candidate[position]
        if position < len(kinds) and kinds[position] and not _matches_kind(merged, kinds[position]):
            score += 1
        if constrained == 0:
            score = -abs((width - 1) - position)
        if best_score is None or score > best_score:
            best_score = score
            best_position = position

    return row[:best_position] + [
        ",".join(row[best_position:best_position + extra + 1])
    ] + row[best_position + extra + 1:]

def parse_csv(raw_csv: str):
    if not isinstance(raw_csv, str):
        raw_csv = str(raw_csv)

    try:
        reader = csv.reader(
            io.StringIO(raw_csv, newline=""),
            delimiter=",",
            quotechar='"',
            doublequote=True,
            strict=False
        )
        records = list(reader)
    except (csv.Error, TypeError, ValueError):
        records = []

    nonblank_indexes = [
        index for index, row in enumerate(records) if not _is_blank(row)
    ]
    if not nonblank_indexes:
        return {"columns": [], "rows": []}

    expected_width = 9
    header_index = None
    exact_candidates = [
        index for index in nonblank_indexes if len(records[index]) == expected_width
    ]

    if exact_candidates:
        for index in exact_candidates:
            following = None
            for later in range(index + 1, len(records)):
                if not _is_blank(records[later]):
                    following = records[later]
                    break
            if _header_score(records[index], following) >= 4:
                header_index = index
                break
        if header_index is None:
            header_index = exact_candidates[0]
    else:
        header_index = nonblank_indexes[0]

    header = [str(value) for value in records[header_index]]
    header = _normalize_row(header, expected_width)
    if header:
        header[0] = header[0].lstrip("\ufeff")

    rows = []
    for row in records[header_index + 1:]:
        rows.append(_normalize_row(row, expected_width, header))

    return {"columns": header, "rows": rows}
